import React, { useState, useEffect } from "react";
import axios from "axios";
import { useCart } from "../components/CartContext";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";

const Products = () => {
  const [products, setProducts] = useState([]);
  const [groupedProducts, setGroupedProducts] = useState({});
  const { addToCart } = useCart();
  const navigate = useNavigate();
  const isAdmin = localStorage.getItem("isAdmin") === "true";

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/products");
      setProducts(res.data);
      groupByCategory(res.data);
    } catch (error) {
      toast.error("Error fetching products");
    }
  };

  const groupByCategory = (products) => {
    const grouped = {};
    products.forEach((product) => {
      const category = product.category || "Others";
      if (!grouped[category]) grouped[category] = [];
      grouped[category].push(product);
    });
    setGroupedProducts(grouped);
  };

  const handleDelete = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/products/${id}`);
      toast.success("Product deleted");
      fetchProducts();
    } catch (err) {
      toast.error("Failed to delete");
    }
  };

  return (
    <div className="bg-gray-100 min-h-screen p-4">
      {Object.entries(groupedProducts).map(([category, items]) => (
        <div key={category} className="mb-8">
          <h2 className="text-2xl font-semibold text-gray-800 mb-3 px-2">{category}</h2>
          <div className="flex overflow-x-auto gap-4 px-2 pb-4">
            {items.map((product) => (
              <div
                key={product._id}
                className="min-w-[200px] max-w-[200px] bg-white rounded-2xl shadow-md hover:shadow-lg transition duration-300 p-3 relative group"
              >
                <img
                  src={product.image}
                  alt={product.name}
                  className="h-40 w-full object-cover rounded-xl"
                />
                <h3 className="text-md font-medium mt-2 text-gray-700">{product.name}</h3>
                <p className="text-sm text-gray-600">{product.brand}</p>
                <p className="text-lg font-semibold text-green-600">₹{product.price}</p>
                <div className="mt-2 flex justify-between items-center">
                  <button
                    className="bg-yellow-500 text-white text-sm px-3 py-1 rounded hover:bg-yellow-600"
                    onClick={() => addToCart(product)}
                  >
                    Add to Cart
                  </button>
                  {isAdmin && (
                    <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition">
                      <button
                        className="text-xs bg-blue-600 text-white px-2 py-1 rounded"
                        onClick={() => navigate(`/product/${product._id}`)}
                      >
                        View
                      </button>
                      <button
                        className="text-xs bg-red-600 text-white px-2 py-1 rounded"
                        onClick={() => handleDelete(product._id)}
                      >
                        Delete
                      </button>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default Products;
